import {createState,checksum,evaluate,ruleErrors,quoteErrors,convert,round,buildLedger,SOURCES,DEMO_RATES} from './engine.mjs';
const STORAGE='datum-ift-fee-workbench.v1';
let state;try{const saved=JSON.parse(localStorage.getItem(STORAGE));state=saved?.schema===1?saved:createState();}catch{state=createState();}
let view='overview',paymentStep=1,selectedRule=null,selectedLog=null,apiTab='response',busy=false,filter='',pendingAction=null;
const ROLE_NAMES={OPS_MAKER:'Bank · Fee configurator',OPS_CHECKER:'Bank · Fee approver',CORP_MAKER:'Corporate · Payment maker',CORP_CHECKER:'Corporate · Payment approver',OBSERVER:'Trainer · Observer only'};
const ACTORS={OPS_MAKER:'ops.maker.demo',OPS_CHECKER:'ops.checker.demo',CORP_MAKER:'corp.maker.demo',CORP_CHECKER:'corp.checker.demo',OBSERVER:'trainer.demo'};
const NAV=[['overview','01','Overview'],['tariffs','02','T24 configuration'],['sync','03','Tariff sync'],['payment','04','IFT · New payment'],['approvals','05','Approve & execute'],['api','06','API Explorer'],['accounting','07','Accounting & reconciliation'],['audit','08','Audit trail'],['scenarios','09','Scenario lab'],['guide','10','Guide & glossary']];
const SYNC_NAMES=['Publish event','Gateway receives','Read snapshot','Validate schema','Apply to IFT','Send ACK','Reconcile version'];
const uid=p=>`${p}.${++state.seq}`;
const now=()=>Date.now()+state.clockOffset;
const stamp=()=>new Date(now()).toISOString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,c='USD')=>`${Number(v||0).toLocaleString('en-US',{minimumFractionDigits:['JPY','VND'].includes(c)?0:2,maximumFractionDigits:['JPY','VND'].includes(c)?0:2})} ${c}`;
const date=v=>v?new Date(v).toLocaleString('en-GB',{hour12:false}):'—';
const pretty=v=>esc(JSON.stringify(v,null,2));
const badge=(v,type='')=>`<span class="badge ${type}"><i class="dot"></i>${esc(v)}</span>`;
const button=(label,action,cls='',disabled=false,attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${disabled?'disabled':''} ${attrs}>${label}</button>`;
const help=key=>`<button class="help" data-action="help" data-key="${key}" aria-label="Explain ${esc(key)}">?</button>`;
const empty=(title,desc)=>`<div class="empty"><b>${title}</b>${desc}</div>`;
const heading=(eyebrow,title,description,actions='')=>`<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><div class="subtle">${description}</div></div><div class="actions">${actions}</div></div>`;
const panel=(title,content,actions='',body=true)=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${actions}</div>${body?`<div class="panel-body">${content}</div>`:content}</section>`;
const notice=(text,type='')=>`<div class="notice ${type}">${text}</div>`;
const getQuote=()=>state.quotes.find(q=>q.id===state.selectedQuote);
const getPayment=()=>state.payments.find(p=>p.id===state.selectedPayment)||state.payments[0];
const can=role=>state.role===role;
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('Could not save in this browser; export a snapshot to keep the demo session.',true);}};
function audit(action,detail,entity='SYSTEM'){state.audit.unshift({id:uid('AUD'),at:stamp(),actor:ACTORS[state.role],role:state.role,action,entity,detail});if(state.audit.length>500)state.audit.length=500;save();}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',5000);}
function showDialog(title,content,footer='',large=false){document.querySelector('#overlay').innerHTML=`<div class="dialog-backdrop"><div class="dialog ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="panel-head"><h2>${title}</h2>${button('Close ×','close','ghost small')}</div><div class="panel-body">${content}</div>${footer?`<div class="panel-head">${footer}</div>`:''}</div></div>`;document.querySelector('#overlay button')?.focus();}
function closeDialog(){document.querySelector('#overlay').innerHTML='';}
function field(label,name,value,type='text',hint='',options=null){return `<div class="field"><label for="f-${name}">${label}</label>${options?`<select id="f-${name}" name="${name}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${type==='number'?'step="any" min="0"':''}>`}${hint?`<small>${hint}</small>`:''}</div>`;}
function flow(){return `<div class="flow">${[['T24 mock','Approved tariff',`v${state.active.version}`],['API Gateway','Tracing & control','SIMULATED'],['IFT Fee Catalog','Versioned replica',`v${state.ift.version}`],['IFT Portal','Fee quote for corporates','CORPORATE'],['Core posting','Fee collection & reconciliation','SANDBOX']].map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<div class="flow-node ${i===0||i===2?'live':''}">${badge(n[2],i===2&&state.active.version!==state.ift.version?'amber':'')}<b>${n[0]}</b><small>${n[1]}</small></div>`).join('')}</div>`;}
function render(){const synced=state.active.version===state.ift.version;document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">ƒ</div><div><strong>Datum Bank · IFT</strong><small>FEE OPERATIONS LAB</small></div></div><div class="nav-label">PRACTICE WORKSPACE</div><nav class="nav">${NAV.map(([id,n,label])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}"><span class="num">${n}</span>${label}</button>`).join('')}</nav><div class="sidebar-foot"><b>SIMULATION · FAKE DATA</b><br>No connection to T24, SWIFT or a real bank. APIs run inside the browser.<br><button class="btn ghost small" style="color:#c5d7ca;padding-left:0" data-action="sources">Sources & simulation scope ↗</button></div></aside><div class="workspace"><header class="topbar"><div class="actions"><button class="btn small menu-toggle" data-action="menu">☰</button><div class="breadcrumb">Corporate payments <span style="margin:0 12px;color:#bbc7b3">/</span> <b>${NAV.find(x=>x[0]===view)?.[2]}</b></div></div><div class="top-actions">${badge(synced?'T24 ↔ IFT in sync':'IFT is behind on version',synced?'':'amber')}<select id="role" class="role-select" aria-label="Acting role">${Object.entries(ROLE_NAMES).map(([key,label])=>`<option value="${key}" ${state.role===key?'selected':''}>${label}</option>`).join('')}</select><div class="avatar">${state.role.startsWith('CORP')?'CO':'BK'}</div>${button('?','help','small','',`data-key="start"`)}</div></header><main class="main">${renderView()}<div class="footer-note"><span>DATUM BANK · IFT FEE WORKBENCH · Private training session · State saved in this browser</span><span>Logical API / GL / field mock · Not a standard Temenos screen or API</span></div></main></div></div>`;}
function renderView(){return {overview:overviewView,tariffs:tariffView,sync:syncView,payment:paymentView,approvals:approvalView,api:apiView,accounting:accountingView,audit:auditView,scenarios:scenarioView,guide:guideView}[view]();}
function overviewView(){const demoQuote=(()=>{try{return evaluate(createState().form,state.active,now());}catch{return null;}})();const demoOwn=demoQuote?.components.find(c=>c.component==="OWN_FEE");const collected=state.payments.filter(p=>['COMPLETED','POSTED','UNKNOWN','RECONCILED'].includes(p.status));return heading('INTERNATIONAL FUND TRANSFER','From fee tariff to a single transfer','One end-to-end flow to configure, explain, check and trace international payment fees.',button('Start the guided journey','walkthrough','primary')+button('Export demo session','export',''))+`<div class="grid four">${[['T24 version',`v${state.active.version}`,`${state.active.rules.filter(r=>r.enabled).length} rules enabled`],['IFT fee catalog',`v${state.ift.version}`,state.ift.version===state.active.version?'Matches the source snapshot':'Sync required before quoting'],['Payments',state.payments.length,`${collected.length} payments with a core result`],['API traces',state.logs.length,'Request · response · correlation ID']].map(([l,v,f])=>`<div class="stat"><div class="label">${l}</div><div class="value">${v}</div><div class="foot">${f}</div></div>`).join('')}</div><div class="hero"><div class="hero-copy"><div class="eyebrow">LEARN WITH ONE REAL TRANSACTION IN THE MOCK</div><h2>The same fee.<br>Seen from both sides.</h2><p>The bank sets up and approves the rules. The corporate sees how the fee is calculated, who pays it and the total amount before confirming.</p><div class="actions">${button('Open T24 configuration →','go-tariff','dark')}${button('View customer IFT','go-payment')}</div></div><div class="hero-art"><div class="stack-card"><div class="mini">T24 · FEE RULE</div><div class="big">${demoOwn?(demoOwn.method==="PERCENT"?(demoOwn.rate*100).toFixed(2):demoOwn.net.toFixed(2)):"—"}<span style="font-size:15px">${demoOwn?.method==="PERCENT"?"%":" USD"}</span></div><div class="mini">MIN ${demoOwn?.min??"—"} · MAX ${demoOwn?.max??"∞"} USD</div><div class="line"></div><div class="line" style="width:45%"></div></div><span class="connector">↔</span><div class="stack-card back"><div class="mini">IFT · APPLIED FEE</div><div class="big">${demoQuote?demoQuote.totalFees.toFixed(2):"—"}</div><div class="mini">USD · BEFORE TAX</div><div class="line"></div><div class="line" style="width:45%"></div></div></div></div>${panel('Two independent flows, one tariff version',flow(),badge('REFERENCE DESIGN'),false)}<div class="grid two gap-top">${panel('Practice by role',`<div class="row-list">${[['01','Configure & approve','The bank maker creates a draft; the checker reviews the differences and approves.'],['02','Sync & ACK','The activation event reads the snapshot, validates, applies, ACKs and reconciles.'],['03','Quote & create payment','The corporate maker enters the payment, requests a quote and sends it for approval.'],['04','Execute & check','The checker approves; the core mock debits, sends a simulated message and reconciles.']].map(([n,t,d])=>`<div class="row-item"><span class="step-index">${n}</span><div><h3>${t}</h3><div class="subtle">${d}</div></div></div>`).join('')}</div>`,'',false)}${panel('Session status',`<div class="sum-line"><span>Acting as</span><b>${ROLE_NAMES[state.role]}</b></div><div class="sum-line"><span>Active scenario</span><b>${esc(state.scenario)}</b></div><div class="sum-line"><span>Configuration draft</span><b>${state.draft?'v'+state.draft.version+' · '+state.draft.status:'Not created'}</b></div><div class="sum-line"><span>IFT checksum</span><b>${esc(state.ift.checksum)}</b></div>${notice('Default prices are an illustrative selection from the Datum Bank corporate international transfer tariff effective 01/06/2026. FX, tax, BIC, GL and every API are training assumptions.')}<div class="actions">${button('Try failure scenarios','go-scenarios')}${button('Explain the terms','go-guide')}</div>`)}</div>`;}
function tariffView(){const tariff=state.draft||state.active;return heading('BANK OPERATIONS / T24-STYLE MOCK','Corporate fee tariff configuration','Simulates records, rule-selection conditions and maker–checker. Field names below are logical fields, not the T24 dictionary.',button('Create new version draft','new-draft','primary',!can('OPS_MAKER')||!!state.draft))+`<div class="panel"><div class="status-banner"><div><div class="actions"><h2 class="mono">CORP.IFT.STANDARD</h2>${badge(`v${tariff.version}`)}${badge(tariff.status,tariff.status==='ACTIVE'?'':'amber')}</div><p>Company: DATUM.BANK · Customer type: CORPORATE · Outward IFT · Demo period: ${esc(tariff.effectiveFrom)} → ${esc(tariff.effectiveTo)}</p></div><div class="actions">${state.draft?button('Set effective dates','effective','small',!can('OPS_MAKER')||state.draft.status!=='DRAFT')+button('Compare versions','diff','small'):''}${state.draft?.status==='DRAFT'?button('Submit for approval','submit-draft','primary small',!can('OPS_MAKER')):''}${state.draft?.status==='PENDING_APPROVAL'?button('Approve & activate','approve-draft','primary small',!can('OPS_CHECKER')):''}${state.draft?.status==='PENDING_APPROVAL'?button('Return draft','reject-draft','danger small',!can('OPS_CHECKER')):''}</div></div>${state.draft?notice('You are viewing the draft. Changes do not affect customer quotes until the checker approves. Maker and checker are separate demo accounts.','info'):''}<div class="toolbar"><span class="subtle">${tariff.rules.length} records · Select a row to see every field</span><div class="actions">${button('Add special rule','add-rule','small',!can('OPS_MAKER')||state.draft?.status!=='DRAFT')}${help('priority')}</div></div><div class="table-wrap"><table><thead><tr><th>Record / component</th><th>Conditions</th><th>Calculation</th><th>Min / Max</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody>${tariff.rules.map(r=>`<tr><td><span class="cell-title">${esc(r.name)}</span><span class="cell-sub mono">${esc(r.id)}</span><span class="cell-sub">${esc(r.component)} · Ref ${esc(r.source)}</span></td><td>${esc(r.event)} · ${esc(r.paymentCurrency)} · ${esc(r.bearer)}<span class="cell-sub">${esc(r.channel)} · BIC ${esc(r.bic)}</span></td><td class="nowrap">${r.method==='PERCENT'?(r.rate*100).toFixed(3)+'%':money(r.fixed,r.currency)}<span class="cell-sub">${esc(r.currency)} · Discount ${(r.discount*100).toFixed(0)}%</span></td><td class="mono">${money(r.min,r.currency)}<br>${r.max===null?'No cap':money(r.max,r.currency)}</td><td class="mono">${r.priority}</td><td>${badge(r.enabled?'ENABLED':'DISABLED',r.enabled?'':'gray')}</td><td>${button('Open record','edit-rule','small',false,`data-id="${esc(r.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div><div class="grid two gap-top">${panel('Application mapping to confirm',`<p class="subtle">FT legacy: check <span class="mono">FT.CHARGE.TYPE / FT.COMMISSION.TYPE</span>, transaction type defaulting and correspondent conditions if the environment uses them.</p><p class="subtle">AA / TPH / Enterprise Pricing: map this logic to the product, activity, pricing and payment configuration of the actual release and license.</p>${notice('Do not load the DEMO codes or lab payloads into a real core. This is not a copy of a Temenos screen.')}`)}${panel('Fee selection rules in the lab',`<p class="subtle">Filter by enabled, event, segment, channel, currency, charge bearer and BIC. Within the same fee component, the rule with the highest priority wins.</p><p class="subtle">If two rules share a component and priority: stop with <span class="mono">AMBIGUOUS_RULE</span>. Customer and rule discounts are compounded, after Min/Max in the lab.</p>${button('View condition dictionary','help','small',false,'data-key="rule"')}`)}</div>`;}
function editRule(id,isNew=false){const tariff=state.draft||state.active;let r=tariff.rules.find(r=>r.id===id);if(isNew)r={...structuredClone(state.active.rules[0]),id:'IFT.OUT.CUSTOM',name:'Demo negotiated transfer fee',priority:200,source:'DEMO',bic:'DEMOUS33'};if(!r)return;selectedRule={...structuredClone(r),isNew};const readonly=!can('OPS_MAKER')||state.draft?.status!=='DRAFT';showDialog(`${readonly?'View':'Edit'} fee record`,`${notice('Logical field mock · Price changes are training assumptions, not a new Datum Bank tariff.','info')}<form id="rule-form"><div class="form-grid">${field('RECORD.ID · Rule ID','id',r.id,'text','Uppercase letters, digits, dots or dashes.')}${field('DESCRIPTION · Fee name','name',r.name)}${field('COMPONENT · Fee component','component',r.component,'text','Each component selects the single highest-priority rule.',['OWN_FEE','SWIFT_FEE','CORRESPONDENT','NODEDUCT','INVESTIGATION','AMENDMENT'])}${field('EVENT · Event','event',r.event,'text','The customer UI in the lab executes OUTWARD.',['OUTWARD','INWARD','INVESTIGATE','AMEND'])}${field('METHOD · Formula','method',r.method,'text','Fixed amount or percentage.',['PERCENT','FIXED'])}${field('FEE.CURRENCY · Fee currency','currency',r.currency,'text','May differ from the payment currency.',Object.keys(DEMO_RATES))}${field('PERCENT · Enter as %','rate',r.rate*100,'number','Enter 0.2 for 0.2%.')}${field('FIXED.AMOUNT · Fixed amount','fixed',r.fixed,'number')}${field('MIN.AMOUNT · Floor','min',r.min,'number')}${field('MAX.AMOUNT · Cap','max',r.max,'number','Leave empty for no cap.')}${field('PAYMENT.CCY · Payment currency','paymentCurrency',r.paymentCurrency,'text','OTHER in the lab = GBP/SGD.',['ANY','USD','EUR','JPY','OTHER'])}${field('CHARGE.BEARER · Fee bearer','bearer',r.bearer,'text','ANY matches every supported option.',['ANY','OUR','SHA','BEN'])}${field('CHANNEL · Channel','channel',r.channel,'text','The channel must match the quote data.',['ANY','IFT_WEB','H2H_API','BRANCH'])}${field('SEGMENT · Segment','segment',r.segment,'text','Do not apply the retail tariff to corporates.',['CORPORATE','CORPORATE_PREMIUM','ANY'])}${field('INTERMEDIARY.BIC · Route','bic',r.bic,'text','ANY or the demo BIC DEMOUS33.')}${field('PRIORITY · Priority order','priority',r.priority,'number','Higher numbers win; a tie is an error.')}${field('DISCOUNT.PCT · Discount after Min/Max','discount',r.discount*100,'number','100 means a full waiver.')}${field('GL.CATEGORY · Accounting','gl',r.gl,'text','Demo GL; own fee differs from correspondent payable.')}<div class="field full"><label>Scope note</label><textarea name="description">${esc(r.description)}</textarea></div><label class="check"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}>Enable rule</label><label class="check"><input type="checkbox" name="taxable" ${r.taxable?'checked':''}>Allow demo tax when the user turns it on</label></div><div class="notice">Source: ${esc(r.source)}. Conditions, FX, discount and GL in the lab are assumptions. Only the selected reference prices trace back to the Datum Bank tariff.</div>${readonly?notice('Switch to the “Bank · Fee configurator” role and create a draft to edit.'):button('Save to draft','save-rule','primary')}</form>`,'',true);if(readonly)document.querySelectorAll('#rule-form input,#rule-form select,#rule-form textarea').forEach(el=>el.disabled=true);}
function syncView(){const run=state.syncRuns[0];return heading('CONFIGURATION DISTRIBUTION','Tariff sync T24 → IFT','Syncs a versioned snapshot. The per-transaction quote API is a separate flow on the IFT screen.',button(busy?'Syncing…':'Sync approved version','sync','primary',busy||!can('OPS_MAKER')))+`<div class="grid three">${[['T24 source',state.active.version,checksum(state.active.rules)],['IFT replica',state.ift.version,state.ift.checksum],['Latest ACK',state.ift.lastAck,date(state.ift.appliedAt)]].map(([t,v,c])=>`<div class="stat"><div class="label">${t}</div><div class="value">${typeof v==='number'?'v'+v:esc(v)}</div><div class="foot mono">${esc(c)}</div></div>`).join('')}</div><div class="panel gap-top"><div class="panel-head"><h2>Sync pipeline · 7 steps</h2>${badge(run?.status||'NOT RUN',run?.status==='FAILED'?'red':'')}</div><div class="sync-steps">${SYNC_NAMES.map((name,i)=>`<div class="sync-step clickable ${run?.steps[i]?.status==='OK'?'done':run?.steps[i]?.status==='FAILED'?'failed':''}" data-action="sync-step" data-step="${i}" role="button" tabindex="0" aria-label="Step ${i+1} details: ${name}"><span class="mono">0${i+1}</span><b>${name}</b><small>${run?.steps[i]?.status||'WAITING'}</small></div>`).join('')}</div>${notice('In the lab: the event is published only after checker approval. The consumer checks version + checksum, stages the snapshot, then applies it as a whole. A repeat with the same version/hash is ACKed without reapplying.','info')}<div class="panel-body"><div class="form-grid">${field('Sync scenario','syncScenario',state.scenario,'text','Choose in the Scenario lab to keep things consistent.',[['NORMAL','Normal'],['SYNC_FAIL','Simulate validation failure'],['OLD_EVENT','Old event arrives late']])}<div><h3>Control gate conditions</h3><div class="subtle">Version increments correctly · Valid payload · No duplicate rule IDs · Min ≤ Max · Checksum matches · No downgrade.</div></div></div></div></div><div class="grid two gap-top">${panel('Run history',state.syncRuns.length?`<div class="table-wrap"><table><thead><tr><th>Run / version</th><th>Result</th><th>Time</th></tr></thead><tbody>${state.syncRuns.slice(0,10).map(r=>`<tr><td class="mono">${esc(r.id)}<span class="cell-sub">v${r.version} · ${esc(r.checksum)}</span></td><td>${badge(r.status,r.status==='FAILED'?'red':'')}</td><td class="subtle">${date(r.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No sync runs yet','You can rerun v1 to see an idempotent ACK.'),'',false)}${panel('Snapshot and API contract',`<p class="subtle">All endpoints are illustrative. A real T24 may use OFS, service APIs, an integration adapter or an event flow depending on the architecture.</p><pre class="code">${pretty({eventType:'FeeTariff.Activated',tariffId:state.active.id,version:state.active.version,checksum:checksum(state.active.rules),effectiveFrom:state.active.effectiveFrom,ruleCount:state.active.rules.length})}</pre><div class="actions gap-top">${button('View request / response','go-api')}${button('Deliberately make IFT stale','stale','small',!can('OPS_MAKER'))}</div>`)}</div>`;}
function quoteSummary(q){return `<div class="panel summary"><div class="panel-head"><h2>Applied fees</h2>${q?badge('v'+q.tariffVersion):badge('NOT QUOTED','gray')}</div><div class="panel-body">${q?`<div class="mini-title">Quote ${esc(q.id)}</div><div class="sum-line"><span>Transfer amount</span><b>${money(q.principal,q.input.currency)}</b></div>${q.components.map(c=>`<div class="sum-line"><span>${esc(c.name)}<span class="cell-sub">${esc(c.payer)} · ${esc(c.currency)}</span></span><b>${money(c.feeSettlement,q.input.feeCurrency)}</b></div>`).join('')}<div class="sum-line"><span>Tax ${q.input.taxEnabled?'(assumed)':'not assessed'}</span><b>${q.input.taxEnabled?money(q.tax,q.input.feeCurrency):'Not included'}</b></div><div class="total"><div class="mini-title">${q.input.bearer==='BEN'?'FEES DEDUCTED FROM TRANSFER':'TOTAL FEES PAID BY SENDER'}</div><div class="amount">${money(q.totalFees,q.input.feeCurrency)}</div><div class="subtle">${q.totalDebit!==null?'Total debit: '+money(q.totalDebit,q.input.currency):'Principal and fees are debited in two separate currencies'}</div></div><div class="sum-line"><span>Amount sent, before external charges</span><b>${money(q.transferAmount,q.input.currency)}</b></div><div class="subtle gap-top">Quote valid until: ${date(q.expiresAt)}<br>The 120-second price lock is a lab assumption.</div>${button('View each fee formula','quote-detail','small',false,`data-id="${esc(q.id)}"`)}${notice(q.warnings.join('<br>'))}`:empty('No quote yet','Enter the payment, then choose “Save & get fees”.')}<div class="subtle gap-top">Demo FX: 1 USD = 25,000 VND. Other fixed rates are listed in the guide.</div></div></div>`;}
function paymentView(){const f=state.form,q=getQuote();const mismatch=state.ift.version!==state.active.version;const steps=['Payment details','Quote & explanation','Review & submit'];return heading('CORPORATE IFT PORTAL','New international payment','Corporate maker role. Data, accounts and beneficiary banks are all fictitious.',button('Load 10,000 USD sample','sample','',!can('CORP_MAKER')))+`<div class="tabs">${steps.map((s,i)=>`<button data-action="payment-step" data-step="${i+1}" class="${paymentStep===i+1?'active':''}">0${i+1} · ${s}</button>`).join('')}</div>${mismatch?notice(`T24 v${state.active.version} and IFT v${state.ift.version} do not match. The lab blocks quotes until they are synced. This demo policy prevents using stale configuration.`,'error'):''}${!can('CORP_MAKER')?notice('Choose the “Corporate · Payment maker” role to get fees and submit. You can still view the data in other roles.','info'):''}<div class="split"><div>${paymentStep===1?`<form id="payment-form" class="panel"><div class="form-section"><div class="section-title"><span class="step">01</span><h3 class="no-margin">Company & source of funds</h3></div><div class="form-grid">${field('Company','company',f.company)}${field('Customer ID / CIF','cif',f.cif,'text','Demo CIF; do not enter real data.')}${field('Source account','account',f.account)}${field('Transfer currency','currency',f.currency,'text','Changing currency uses the demo balance in that currency.',['USD','EUR','JPY','GBP','SGD'])}${field('Transfer amount','amount',f.amount,'number','Principal, excluding fees.')}${field('Fee currency','feeCurrency',f.feeCurrency,'text','Fees can be collected in USD or converted to VND.',Object.keys(DEMO_RATES))}</div><div class="notice info">Available demo balance: <b>${money(state.balances[f.currency],f.currency)}</b>. When fees are in another currency, the lab checks each currency account separately.</div></div><div class="form-section"><div class="section-title"><span class="step">02</span><h3 class="no-margin">Beneficiary & payment route</h3></div><div class="form-grid">${field('Beneficiary','beneficiary',f.beneficiary)}${field('Beneficiary account','beneficiaryAccount',f.beneficiaryAccount)}${field('Country','country',f.country)}${field('Beneficiary bank BIC','bic',f.bic,'text','DEMOSGSG is a fictitious BIC in the lab.')}${field('Intermediary BIC','intermediary',f.intermediary,'text','DEMOUS33 is a fictitious BIC; you can create a specific rule for it.')}${field('Channel','channel',f.channel,'text','Sent in the quote request.',['IFT_WEB','H2H_API','BRANCH'])}<div class="field full"><label for="purpose">Purpose of payment</label><textarea id="purpose" name="purpose">${esc(f.purpose)}</textarea></div></div></div><div class="form-section"><div class="section-title"><span class="step">03</span><h3 class="no-margin">Fee bearer & commercial terms</h3></div><div class="form-grid">${field('Fee bearer · charge bearer','bearer',f.bearer,'text','OUR: sender pays; SHA: shared; BEN: fees deducted from the transfer in the lab.',[['OUR','OUR · Sender pays'],['SHA','SHA · Shared fees'],['BEN','BEN · Beneficiary pays']])}${field('Customer segment','segment',f.segment,'text','CORPORATE rules do not match other segments automatically.',['CORPORATE','CORPORATE_PREMIUM'])}<div class="field"><label>Customer-specific discount</label><input value="No special agreement in the demo" readonly><small>Customers cannot enter their own discount. The bank configures discounts in the fee record and approves them.</small></div>${field('Demo tax (%)','taxRate',f.taxRate*100,'number','Applies only when the tax simulation option is on.')}<label class="check"><input type="checkbox" name="nodeDuct" ${f.nodeDuct?'checked':''}>Add demo NODEDUCT, OUR only ${help('OUR')}</label><label class="check"><input type="checkbox" name="taxEnabled" ${f.taxEnabled?'checked':''}>Turn on assumed tax for training ${help('tax')}</label></div></div><div class="panel-head"><span class="subtle">Saving invalidates the previous quote if the context changed.</span>${button('Save & get fees →','quote','primary',busy||!can('CORP_MAKER')||mismatch)}</div></form>`:paymentStep===2?renderQuoteBreakdown(q):renderReview(q)}</div>${quoteSummary(q)}</div>`;}
function renderQuoteBreakdown(q){if(!q)return panel('Transaction quote',empty('Get a quote first','Go back to payment details, enter the data and call the fee API.'),button('← Payment details','payment-step','small',false,'data-step="1"'));return `<div class="panel"><div class="panel-head"><h2>How each component is calculated</h2>${button('API for this quote','quote-api','small',false,`data-id="${q.id}"`)}</div>${q.components.map((c,i)=>`<div class="form-section"><div class="actions" style="justify-content:space-between"><h3>${i+1}. ${esc(c.name)}</h3>${badge(c.component,c.component==='CORRESPONDENT'?'blue':'')}</div><div class="mono subtle">${esc(c.ruleId)} · Ref ${esc(c.source)} · ${esc(c.payer)}</div><div class="review-line"><span>Converted calculation base</span><b>${money(c.base,c.currency)}</b></div><div class="review-line"><span>Base formula</span><b>${c.method==='PERCENT'?`${money(c.base,c.currency)} × ${(c.rate*100).toFixed(3)}%`:`Fixed ${money(c.fixed,c.currency)}`} = ${money(c.raw,c.currency)}</b></div><div class="review-line"><span>Apply Min / Max</span><span>Min ${money(c.min,c.currency)} · Max ${c.max===null?'no limit':money(c.max,c.currency)} → <b>${money(c.bounded,c.currency)}</b></span></div><div class="review-line"><span>Discount after Min/Max</span><span>${(c.discount*100).toFixed(2)}% → <b>${money(c.net,c.currency)}</b></span></div><div class="review-line"><span>Converted to fee currency</span><b>${money(c.feeSettlement,c.settlementCurrency)}</b></div><div class="review-line"><span>Tax</span><span>${c.taxStatus==='NOT_ASSESSED'?'Not assessed; this does not mean 0%':money(c.taxSettlement,c.settlementCurrency)+' · '+c.taxStatus}</span></div></div>`).join('')}<div class="panel-head"><span class="subtle">T24 returns the breakdown with the version and context hash.</span>${button('Continue to review →','payment-step','primary',false,'data-step="3"')}</div></div><div class="panel gap-top"><div class="panel-head"><h2>Rule evaluation · Why did a rule apply or not?</h2>${help('rule')}</div><div class="table-wrap"><table><thead><tr><th>Rule</th><th>Result</th><th>Unmatched conditions</th></tr></thead><tbody>${q.traces.map(t=>`<tr><td class="mono">${t.ruleId}</td><td>${badge(t.qualified?'QUALIFIED':'NOT MATCHED',t.qualified?'':'gray')}</td><td class="subtle">${Object.entries(t.checks).filter(([,ok])=>!ok).map(([key])=>key).join(', ')||'All conditions match; next selected by priority within the component'}</td></tr>`).join('')}</tbody></table></div></div>`;}
function renderReview(q){if(!q)return panel('Review payment',empty('No quote yet','Get fees before sending for approval.'));const error=quoteErrors(q,state,now());return panel('Review & accept the fees',`${[['Company',q.input.company],['Beneficiary',q.input.beneficiary],['Beneficiary account',q.input.beneficiaryAccount],['Bank / intermediary',q.input.bic+' / '+q.input.intermediary],['Purpose',q.input.purpose],['Amount',money(q.principal,q.input.currency)],['Fee bearer',q.input.bearer],['Quote / version',q.id+' / v'+q.tariffVersion]].map(([l,v])=>`<div class="review-line"><span>${l}</span><b>${esc(v)}</b></div>`).join('')}${error?notice(`Cannot submit: ${error}. Go back and get a new quote.`,'error'):notice('The payment goes to the corporate checker; nothing is debited at the maker step.','info')}<label class="check gap-top"><input id="consent" type="checkbox">I have reviewed the fee components, FX assumptions, tax scope and external charge conditions.</label><div class="actions gap-top">${button('← Edit','payment-step','',false,'data-step="1"')}${button('Send for approval','submit-payment','primary',!can('CORP_MAKER')||!!error||busy)}</div>`);}
function approvalView(){const p=getPayment();return heading('CORPORATE CHECKER / EXECUTION','Approve payments & track execution','The maker submits; a checker with a different account confirms. Fee status and payment status are tracked separately.',button('New payment','go-payment','primary'))+`<div class="panel"><div class="panel-head"><h2>Demo payments</h2><span class="view-count">${state.payments.length} PAYMENTS</span></div>${state.payments.length?`<div class="table-wrap"><table><thead><tr><th>Payment / time</th><th>Beneficiary</th><th>Amount</th><th>Fees</th><th>Status</th><th></th></tr></thead><tbody>${state.payments.map(x=>`<tr><td><b class="mono">${x.id}</b><span class="cell-sub">${date(x.createdAt)}</span></td><td>${esc(x.quote.input.beneficiary)}</td><td class="number">${money(x.quote.principal,x.quote.input.currency)}</td><td class="number">${money(x.quote.totalFees,x.quote.input.feeCurrency)}</td><td>${badge(x.status,['UNKNOWN','PENDING_APPROVAL'].includes(x.status)?'amber':x.status==='FAILED'?'red':'')}</td><td>${button('View','select-payment','small',false,`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No payments awaiting approval','Create a quote in IFT and submit it with the corporate maker role.')}</div>${p?`<div class="grid two gap-top">${panel('Payment '+p.id,`<div class="review-line"><span>Maker</span><b class="mono">${esc(p.maker)}</b></div><div class="review-line"><span>Checker</span><b class="mono">${esc(p.checker||'Not approved')}</b></div><div class="review-line"><span>Tariff version</span><b>v${p.quote.tariffVersion} / current T24 v${state.active.version}</b></div><div class="review-line"><span>Idempotency key</span><b class="mono">${p.idempotencyKey}</b></div><div class="review-line"><span>Principal debited</span><b>${money(p.quote.principal,p.quote.input.currency)}</b></div><div class="review-line"><span>Fees paid by sender</span><b>${money(p.quote.senderFees,p.quote.input.feeCurrency)}</b></div><div class="review-line"><span>Fee status</span><b>${esc(p.feeStatus)}</b></div><div class="actions gap-top">${p.status==='PENDING_APPROVAL'?button('Approve & execute','approve-payment','primary',!can('CORP_CHECKER')||busy):''}${p.status==='PENDING_APPROVAL'?button('Reject payment','reject-payment','danger',!can('CORP_CHECKER')||busy):''}${p.status==='UNKNOWN'?button('Query core status','query-core','primary',busy||!can('CORP_CHECKER')):''}${['COMPLETED','POSTED','RECONCILED'].includes(p.status)?button('Resend with the same idempotency key','retry-posting','small',busy||!can('CORP_CHECKER')):''}${button('Fee details','quote-detail','small',false,`data-id="${p.quote.id}"`)}</div>${p.error?notice(esc(p.error),'error'):''}${p.status==='UNKNOWN'?notice('The core may have debited even though the API timed out. Query first; do not create a new key to collect again.','error'):''}`)}${panel('Processing timeline',`<div class="timeline">${p.timeline.map(t=>`<div class="timeline-item"><small>${date(t.at)}</small><b>${esc(t.title)}</b><div class="subtle">${esc(t.detail)}</div></div>`).join('')}</div>`,'',false)}</div>`:''}`;}
function apiView(){const logs=filter?state.logs.filter(l=>JSON.stringify(l).toLowerCase().includes(filter.toLowerCase())):state.logs;const selected=state.logs.find(l=>l.id===selectedLog)||logs[0];return heading('OBSERVABILITY / SIMULATED API','API Explorer','Each row is a mock call executed in the browser, with request, response, headers, timing and errors.',button('Export API log','export-logs')+button('Clear filter','clear-filter','',!filter))+panel('Data flow diagram',flow(),badge('NO EXTERNAL REQUESTS','blue'),false)+`<div class="grid two gap-top"><section class="panel"><div class="toolbar"><input id="log-filter" class="search" placeholder="Search endpoint, quote, payment, correlation…" value="${esc(filter)}"><span class="view-count">${logs.length} CALLS</span></div><div class="trace-list">${logs.length?logs.map(l=>`<div class="trace-row ${selected?.id===l.id?'selected':''}" data-action="select-log" data-id="${l.id}" tabindex="0"><span class="method">${l.method}</span><div class="detail"><div class="endpoint">${esc(l.path)}</div><div class="meta">${esc(l.from)} → ${esc(l.to)} · ${l.duration} ms<br>${esc(l.correlationId)} · ${date(l.at)}</div></div><span class="status ${l.status>=400?'error':''}">${l.status}</span></div>`).join(''):empty('No API calls yet','Run a sync or get a quote to generate logs.')}</div></section><section class="panel"><div class="panel-head"><h2>Call details</h2>${selected?button('Copy JSON','copy-log','small',false,`data-id="${selected.id}"`):''}</div><div class="panel-body">${selected?`<div class="mono">${esc(selected.method+' '+selected.path)}</div><p class="subtle">${esc(selected.purpose)}</p><div class="tabs">${['response','request','headers','explain'].map(t=>`<button data-action="api-tab" data-tab="${t}" class="${apiTab===t?'active':''}">${{response:'Response',request:'Request',headers:'Headers',explain:'Explanation'}[t]}</button>`).join('')}</div>${apiTab==='explain'?`<p>${esc(selected.explanation)}</p><div class="review-line"><span>Correlation</span><span class="mono">${esc(selected.correlationId)}</span></div><div class="review-line"><span>Time</span><span>${date(selected.at)} · ${selected.duration} ms simulated</span></div>`:`<pre class="code">${pretty(selected[apiTab])}</pre>`}`:empty('Select a call','The payload will appear here.')}</div></section></div>`;}
function accountingView(){const p=getPayment(),entries=p?state.ledger.filter(e=>e.paymentId===p.id):[];const grouped={};for(const e of entries){grouped[e.currency]??={DR:0,CR:0};grouped[e.currency][e.side]+=e.amount;}return heading('FINANCE / FEE RECONCILIATION','Accounting & reconciliation','Simulated journal entries with explanations. DEMO GLs are not a bank chart of accounts.',p?button('Reconcile selected payment','reconcile','primary',!['COMPLETED','POSTED','RECONCILED'].includes(p.status)||busy||!can('OPS_CHECKER')):'')+`<div class="toolbar panel"><span class="subtle">${p?'Viewing '+p.id:'No payment yet'} · Reconciliation requires the Bank / Fee approver role</span>${p?button('Choose another payment','go-approvals','small'):button('New payment','go-payment','small')}</div><div class="grid three gap-top">${[['DR / Debit','The debit side. In this example, Dr on the customer deposit account reduces the customer’s deposit balance.'],['CR / Credit','The credit side. Cr fee income increases fee income; Cr payable increases a liability.'],['Not everything is revenue','Own fee and message fee use demo income GLs. Correspondent/NODEDUCT charges are tracked as payables, assuming collection on behalf of others.']].map(([t,d])=>`<div class="stat"><h3>${t}</h3><div class="subtle">${d}</div></div>`).join('')}</div><div class="panel gap-top"><div class="panel-head"><h2>Simulated journal</h2>${badge(entries.length+' ENTRIES',entries.length?'':'gray')}</div>${entries.length?`<div class="table-wrap"><table><thead><tr><th>Side</th><th>Demo GL account</th><th>Component</th><th>Amount</th><th>Explanation</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${badge(e.side,e.side==='DR'?'blue':'')}</td><td class="mono">${esc(e.account)}</td><td>${esc(e.component)}</td><td class="number">${money(e.amount,e.currency)}</td><td class="subtle">${entryMeaning(e)}</td></tr>`).join('')}</tbody></table></div>`:empty('No entries yet','Approve and execute a payment to see the principal and each fee component.')}</div><div class="recon-grid gap-top">${Object.entries(grouped).map(([ccy,total])=>`<div class="ok-box"><div class="mini-title">${ccy} BALANCE</div><p class="mono">Dr ${money(total.DR,ccy)}<br>Cr ${money(total.CR,ccy)}</p>${badge(Math.abs(total.DR-total.CR)<0.01?'BALANCED':'UNBALANCED',Math.abs(total.DR-total.CR)<0.01?'':'red')}</div>`).join('')}</div>${p?`<div class="grid two gap-top">${panel('Reconciliation by component',p.recon?`<pre class="code light">${pretty(p.recon)}</pre>`:empty('Not reconciled','Click “Reconcile selected payment” to compare the quote, core posting and journal.'))}${panel('Correspondent fee: estimate vs actual',`<p class="subtle">The amount collected in advance is an estimate. Enter a demo actual to see the difference. The lab only records an exception; it never collects the difference on its own.</p><div class="form-grid">${field('Correspondent actual · USD','actualFee',p.externalActual??20,'number','Assumed amount from an external debit advice.')}${field('External advice reference','adviceRef',p.adviceRef||'DEMO.ADVICE.001')}</div><div class="actions gap-top">${button('Receive simulated debit advice','external-actual','',!['COMPLETED','RECONCILED','POSTED'].includes(p.status)||!can('OPS_CHECKER')||busy)}</div>${p.externalComparison?notice(`Estimate ${money(p.externalComparison.estimate)} · Actual ${money(p.externalComparison.actual)} · Difference ${money(p.externalComparison.difference)}. ${p.externalComparison.difference?'Review/approval required before collecting more or refunding.':'Matched.'}`,p.externalComparison.difference?'':'info'):''}`)}</div>`:''}${notice('BEN with a different fee currency: the demo journal posts a clearing entry in the fee currency; production needs a full FX bridge. This journal is explanatory and does not simulate full Nostro settlement, EIR or a chart of accounts.')}`;}
function entryMeaning(e){if(e.component==='PRINCIPAL')return e.side==='DR'?'Reduces the customer deposit by the principal.':'Records funds awaiting transfer out; does not prove the beneficiary received them.';if(e.account.startsWith('DEMO.CUSTOMER'))return 'Takes the fee/tax from the customer account.';if(e.account==='DEMO.PAYMENT.CLEARING')return 'Beneficiary-borne fee: deducted from the transfer under the demo policy.';if(e.account==='DEMO.CORR.PAYABLE')return 'Records an amount awaiting external payment/reconciliation; not treated as own income.';if(e.account==='DEMO.TAX.PAYABLE')return 'Assumed tax payable, kept separate from revenue.';return 'Records bank fee income under the assumed mapping.';}
function auditView(){return heading('CONTROL / AUDIT TRAIL','Audit trail','Every edit, approval, sync, quote, collection and adjustment has an actor and a reference.',button('Export audit trail','export-audit'))+panel('Audit events',state.audit.length?`<div class="table-wrap"><table><thead><tr><th>Time / ID</th><th>Actor</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td class="subtle">${date(a.at)}<span class="cell-sub mono">${a.id}</span></td><td class="mono">${a.actor}</td><td>${badge(a.action)}</td><td class="mono">${esc(a.entity)}</td><td class="subtle">${esc(typeof a.detail==='string'?a.detail:JSON.stringify(a.detail))}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity yet','Create a draft or get a quote to generate audit events.'),'',false);}
const SCENARIOS=[['NORMAL','01','Normal flow','10,000 USD · OUR · 45 USD fees before tax. Follow each step.'],['SYNC_FAIL','02','Sync failure','Snapshot validation simulates a 422 error; the IFT replica is never half-applied.'],['OLD_EVENT','03','Old event arrives late','The consumer receives a lower version and refuses to downgrade.'],['EXPIRED','04','Expired quote','Get a quote, then move the lab clock forward 180 seconds. Submitting must be blocked.'],['INSUFFICIENT','05','Insufficient funds for fees','Enough for the principal but not principal + fees; no automatic overdraft.'],['CORE_TIMEOUT','06','Core debited, API timed out','The fee was posted but IFT gets a 504. Query the status to recover.'],['DUPLICATE','07','Duplicate submission','Execute, then resend with the same idempotency key; the journal and balance do not change the second time.'],['VERSION_CHANGED','08','Price changes after quoting','Get a quote, approve a new tariff; the old quote must be blocked at the next step.'],['BEN','09','Beneficiary pays fees','In the lab, fees are deducted from the transfer amount; the final amount received is unknown.'],['JPY','10','Fee with a JPY minimum','Transfer 100,000 JPY; correspondent fee 0.1% with a 5,000 JPY minimum.'],['BIC_RULE','11','BIC rule and priority','Add a rule with the same component, BIC DEMOUS33 and a higher priority to override.'],['AMBIGUOUS','12','Two competing rules','Two rules with the same component and priority match at once: AMBIGUOUS_RULE.']];
function scenarioView(){return heading('TRAINING / FAILURE INJECTION','Scenario lab','Choose a scenario, then follow the instructions. No real transactions are created.',(state.scenario==='EXPIRED'?button('Expire quote · +180 seconds','expire','',!getQuote()):'')+button('Reset the whole demo session','reset','danger'))+notice(`Active: <b>${esc(state.scenario)}</b>. ${busy?'A task is running.':''} Scenarios only affect the mock; you can return to NORMAL at any time.`,'info')+`<div class="grid three">${SCENARIOS.map(([id,n,t,d])=>`<div class="scenario-card"><div class="actions" style="justify-content:space-between"><span class="scenario-no">SCENARIO ${n}</span>${state.scenario===id?badge('ACTIVE'):''}</div><h3>${t}</h3><p>${d}</p>${button('Prepare scenario →','scenario','small',busy,`data-scenario="${id}"`)}</div>`).join('')}</div>`;}
const GLOSSARY={
 start:['Getting started','Choose a role in the top right. The bank maker creates, edits and submits a draft. The bank checker activates it. Back as maker, run the sync. The corporate maker gets fees and submits a payment. The corporate checker approves and executes. All APIs and GLs are simulated.'],
 rule:['Rule and component','A rule is a set of conditions + a formula. A component is a fee type, such as OWN_FEE or CORRESPONDENT. Several rules can belong to the same component; the lab selects only the highest-priority rule for that component. On a tie, it stops to avoid picking a price arbitrarily.'],
 priority:['Priority','In the lab, a higher priority number wins after all conditions are filtered. For example, the standard rule has priority 100 and a BIC-specific contract rule has priority 200. This is a reference design, not a field order confirmed by Temenos.'],
 OUR:['OUR / SHA / BEN','OUR: the sender pays fees within the applicable scope. SHA: the sender pays its own bank’s fees; the beneficiary may bear external charges. BEN: fees are deducted from the transfer amount by rule. OUR does not by itself guarantee full receipt; NODEDUCT only applies under service/route conditions. The lab does not claim full amount.'],
 tax:['Tax not assessed is not 0% tax','By default the lab does not determine VAT and states clearly that any tax that may apply is excluded. When demo tax is on, the rate is only a training parameter for flagged rules. Do not use the result as a legal conclusion.'],
 quote:['Quote','A quote includes each component, the version, a context hash and an expiry. The lab simulates a 120-second price hold, but some official Temenos APIs return non-binding quotes. Agree the real quote contract before integrating.'],
 idempotency:['Idempotency · No double charging','One business operation and key has only one debit outcome. On timeout, query the status using the existing key/reference. Do not create a new key just because the client did not receive a response.'],
 sync:['Configuration sync is not fee calculation','Sync moves the approved rule snapshot to IFT so the configuration version is consistent. A quote is a per-payment call through IFT/gateway to the pricing owner. The lab makes the T24 mock the pricing owner and blocks a replica that is behind on version. This is a proposed architecture.'],
 maker:['Maker / checker','The maker enters and submits. A checker with a different account reviews and approves. The lab simulates this with a role selector and separate actors; it is not authentication/SSO or production authorization.'],
 base:['Base / Min / Max','Base is the calculation basis. Percentage fee = base × rate; then the Min floor and Max cap apply. Example: base 1,000 USD × 0.2% = 2 USD; Min is 5 USD, so 5 USD is charged. Min is not an extra amount on top.'],
 fx:['FX / Currency','Currency is the money unit; FX is foreign-exchange conversion. Payment, fee and settlement currencies can differ. The lab keeps the original amount and converts with fixed assumed rates; it does not access real-time rates.'],
 ledger:['Dr / Cr / GL','Dr is debit, Cr is credit; GL is the general ledger. Whether a balance goes up or down depends on the account type. In the example, Dr on the customer deposit account reduces the balance; Cr income records fee income; Cr payable records a liability.'],
 actual:['Estimate / actual / true-up','The estimate is the fee collected in advance under assumptions. The actual is the amount confirmed externally. True-up is the approved handling of the difference; a higher actual does not automatically allow debiting the customer more.'],
 checksum:['Checksum / version / ACK','The version identifies the tariff version. The checksum verifies the snapshot content in the lab (demo FNV, not a security signature). ACK confirms receipt/application. Production needs real authentication, integrity and protection mechanisms.']
};
function guideView(){return heading('REFERENCE / PLAIN LANGUAGE','Guide to the whole system','Follow the transaction: configure → approve → sync → quote → approve payment → debit → reconcile.',button('Open step-by-step guide','walkthrough','primary'))+`<div class="grid two">${panel('Action map',`<div class="row-list">${[['Bank maker','T24 configuration: create a draft, open a record, edit rate/Min/Max or add a BIC condition.'],['Bank checker','Compare versions and approve the draft. The active version increments; IFT does not sync on its own.'],['Bank maker','Sync: run the 7 steps, check the ACK and the version/hash at IFT.'],['Corporate maker','IFT: save the details, get a quote; read the breakdown and each rule match.'],['Corporate maker','Review: tick consent and send for approval. Nothing is debited yet.'],['Corporate checker','Approve & execute; view the timeline, fees and core posting reference.'],['Finance / trainer','View the accounting, reconcile each component; try an actual that differs from the estimate.']].map(([r,d],i)=>`<div class="row-item"><span class="step-index">0${i+1}</span><div><h3>${r}</h3><div class="subtle">${d}</div></div></div>`).join('')}</div>`,'',false)}${panel('Sources and deliberate assumptions',`<p class="subtle">Seed prices are an illustrative selection from the Datum Bank corporate international transfer tariff effective 01/06/2026. They are not the full tariff and may not reflect later updates.</p><p class="subtle">The T24-style interface, API paths, actors, GL, BIC, balances, priority order, price lock, taxes and routing conditions are all lab assumptions.</p><p class="subtle">INWARD/AMEND/INVESTIGATE have sample records; the customer journey currently executes OUTWARD. Real SWIFT/ISO 20022 content, AML, FX execution and real money movement are not simulated.</p><pre class="code light">${pretty({USD_to_base_USD:DEMO_RATES.USD,EUR_to_USD:DEMO_RATES.EUR,JPY_to_USD:DEMO_RATES.JPY,VND_to_USD:DEMO_RATES.VND,GBP_to_USD:DEMO_RATES.GBP,SGD_to_USD:DEMO_RATES.SGD})}</pre><a class="source-link" href="${SOURCES.pricing}" target="_blank" rel="noopener">Temenos · Pricing capabilities ↗</a>`)}</div><div class="grid three gap-top">${Object.entries(GLOSSARY).filter(([key])=>key!=='start').map(([key,[t,d]])=>`<div class="scenario-card"><h3>${t}</h3><p>${d.slice(0,140)}…</p>${button('Read explanation','help','small',false,`data-key="${key}"`)}</div>`).join('')}</div>`;}
function showHelp(key){const [title,body]=GLOSSARY[key]||GLOSSARY.start;document.querySelector('#overlay').innerHTML=`<div class="dialog-backdrop"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Glossary explanation"><div class="drawer-title"><h2>${title}</h2>${button('Close ×','close','small ghost')}</div><div class="drawer-body"><p>${body}</p>${notice('Remark: explanations follow the lab’s training design. Real configuration needs the release documentation and the bank’s policy.')}${button('Open the full guide','guide-close','primary')}</div></aside></div>`;}
function addLog(spec,response,status=200){const duration=90+(state.seq%7)*37;const log={id:uid('API'),at:stamp(),duration,...spec,status,headers:{'x-correlation-id':spec.correlationId,'x-environment':'MOCK_BROWSER_ONLY','x-tariff-version':String(state.active.version),'content-type':'application/json',...(spec.key?{'idempotency-key':spec.key}:{})},response};state.logs.unshift(log);if(state.logs.length>300)state.logs.length=300;selectedLog=log.id;save();return log;}
async function call(spec,response,status=200){await new Promise(resolve=>setTimeout(resolve,140));return addLog(spec,response,status);}
function guard(role){if(!can(role)){toast('This action requires the role: '+ROLE_NAMES[role],true);return false;}if(busy){toast('Wait for the current task to finish.',true);return false;}return true;}
async function runSync(){if(!guard('OPS_MAKER'))return;busy=true;const correlationId=uid('CORR.SYNC'),version=state.scenario==='OLD_EVENT'?state.ift.version-1:state.active.version;const run={id:uid('SYNC'),version,checksum:checksum(state.active.rules),at:stamp(),status:'RUNNING',steps:[]};state.syncRuns.unshift(run);render();const snapshot={tariffId:state.active.id,version,checksum:run.checksum,effectiveFrom:state.active.effectiveFrom,rules:structuredClone(state.active.rules)};const specs=[['T24 mock','Gateway','POST','/mock/events/fee-tariff-activated',{tariffId:snapshot.tariffId,version,checksum:snapshot.checksum},'Publishes the event after approval; drafts are never published.'],['Gateway','Integration adapter','POST','/mock/integration/fee-events',{eventId:run.id,version},'Receives, simulates authentication and identifies the event.'],['Adapter','T24 mock','GET',`/mock/t24/tariffs/${state.active.id}?version=${version}`,{version},'Reads the full snapshot instead of patching rule by rule.'],['Adapter','Validator','POST','/mock/fee-snapshots/validate',snapshot,'Checks schema, version, Min/Max and integrity.'],['Adapter','IFT catalog','PUT',`/mock/ift/fee-catalog/${state.active.id}`,snapshot,'Applies the whole version atomically; never keeps a partial snapshot.'],['IFT catalog','Adapter','POST','/mock/integration/fee-ack',{version,checksum:snapshot.checksum},'An ACK does not replace reconciling the hash and version.'],['Adapter','T24 + IFT','GET','/mock/integration/fee-reconciliation',{version},'Sync counts as complete only when version/hash match.']];try{for(let i=0;i<specs.length;i++){const [from,to,method,path,request,explanation]=specs[i];const validationErrors=snapshot.rules.flatMap(ruleErrors);if(new Set(snapshot.rules.map(r=>r.id)).size!==snapshot.rules.length)validationErrors.push('Duplicate rule ID');const failed=i===3&&(state.scenario==='SYNC_FAIL'||validationErrors.length>0||checksum(snapshot.rules)!==snapshot.checksum);const old=version<state.ift.version&&i===3;const conflict=i===3&&version===state.ift.version&&state.ift.checksum!==snapshot.checksum;const status=failed?422:old||conflict?409:200;let response={status:'OK',version,checksum:run.checksum};if(i===2)response=snapshot;if(failed)response={code:'SNAPSHOT_VALIDATION_FAILED',details:validationErrors.length?validationErrors:['Failure injection: checksum mismatch'],applied:false};if(old)response={code:'STALE_VERSION_REJECTED',incomingVersion:version,currentVersion:state.ift.version,applied:false};if(conflict)response={code:'SAME_VERSION_DIFFERENT_CONTENT',incomingChecksum:snapshot.checksum,currentChecksum:state.ift.checksum,applied:false};if(i===4&&!failed&&!old){const duplicate=version===state.ift.version&&state.ift.checksum===snapshot.checksum;state.ift={version,checksum:snapshot.checksum,rules:structuredClone(snapshot.rules),appliedAt:stamp(),lastAck:state.ift.lastAck};response={status:duplicate?'ALREADY_APPLIED':'APPLIED_ATOMICALLY',version,checksum:snapshot.checksum,ruleCount:snapshot.rules.length};}if(i===5){state.ift.lastAck=uid('ACK');response.ackId=state.ift.lastAck;}await call({from,to,method,path,request,correlationId,purpose:SYNC_NAMES[i],explanation},response,status);run.steps.push({name:SYNC_NAMES[i],status:status>=400?'FAILED':'OK',apiId:selectedLog});save();render();if(status>=400)throw Error(response.code);}run.status='SUCCEEDED';audit('SYNC_COMPLETED',{version,checksum:run.checksum},run.id);toast('Sync complete. IFT now uses v'+state.ift.version);}catch(e){run.status='FAILED';audit('SYNC_FAILED',e.message,run.id);toast('Sync stopped: '+e.message,true);}finally{busy=false;save();render();}}
function readPaymentForm(){const form=document.querySelector('#payment-form');if(!form)return true;const data=new FormData(form);const next={...state.form};for(const name of ['company','cif','account','currency','feeCurrency','beneficiary','beneficiaryAccount','country','bic','intermediary','purpose','channel','segment','bearer'])next[name]=String(data.get(name)||'').trim();next.bic=next.bic.toUpperCase();next.intermediary=next.intermediary.toUpperCase();next.amount=Number(data.get('amount'));next.discount=0;next.taxRate=Number(data.get('taxRate'))/100;next.taxEnabled=data.has('taxEnabled');next.nodeDuct=data.has('nodeDuct');if(next.discount<0||next.discount>1||!Number.isFinite(next.discount)||next.taxRate<0||next.taxRate>1){toast('Discount and demo tax must be between 0 and 100%.',true);return false;}state.form=next;save();return true;}
async function getFees(){if(!guard('CORP_MAKER')||!readPaymentForm())return;busy=true;render();const correlationId=uid('CORR.QUOTE'),request={customerId:state.form.cif,product:'CORP.IFT',event:'OUTWARD',context:structuredClone(state.form),expectedTariffVersion:state.ift.version};try{await call({from:'IFT Portal',to:'IFT API',method:'POST',path:'/mock/ift/fee-quotes',request,correlationId,purpose:'Quote request from the UI',explanation:'The UI never hardcodes prices; it sends the full qualifying context.'},{status:'ACCEPTED',correlationId});if(state.ift.version!==state.active.version){await call({from:'IFT API',to:'Gateway',method:'POST',path:'/mock/pricing/version-check',request:{iftVersion:state.ift.version},correlationId,purpose:'Version check before quoting',explanation:'The lab fails closed when the replica is behind on version.'},{code:'TARIFF_REPLICA_STALE',t24Version:state.active.version,iftVersion:state.ift.version},409);throw Error('TARIFF_REPLICA_STALE');}await call({from:'IFT API',to:'Gateway',method:'POST',path:'/mock/pricing/quotes',request,correlationId,purpose:'Forward the context to the pricing owner',explanation:'In a real deployment, the adapter maps the logical API to a core service.'},{routedTo:'T24_MOCK',contextHash:checksum(state.form)});let q;try{q=evaluate(state.form,state.active,now());}catch(e){await call({from:'Gateway',to:'T24 mock',method:'POST',path:'/mock/t24/fee-assessments/quote',request,correlationId,purpose:'Fee assessment',explanation:'Validation errors or rule conflicts must be returned explicitly.'},{code:e.message},422);throw e;}q.id=uid('QUOTE');q.correlationId=correlationId;await call({from:'Gateway',to:'T24 mock',method:'POST',path:'/mock/t24/fee-assessments/quote',request,correlationId,purpose:'T24 mock selects rules and calculates the breakdown',explanation:'Each rule is evaluated; Min/Max, discount, demo tax and FX follow a fixed order.'},q);await call({from:'IFT API',to:'IFT Portal',method:'REPLY',path:'/mock/ift/fee-quotes/result',request:{quoteId:q.id},correlationId,purpose:'Show fees and conditions to the customer',explanation:'The UI uses the exact version and breakdown; it never recalculates prices itself.'},{quoteId:q.id,version:q.tariffVersion,expiresAt:q.expiresAt,components:q.components,totalFees:q.totalFees,totalDebit:q.totalDebit,warnings:q.warnings});state.quotes.unshift(q);state.selectedQuote=q.id;paymentStep=2;audit('QUOTE_CREATED',{amount:q.principal,currency:q.input.currency,fees:q.totalFees,version:q.tariffVersion},q.id);toast('Quote received: '+q.id);}catch(e){audit('QUOTE_REJECTED',e.message);toast('Could not get fees: '+e.message,true);}finally{busy=false;save();render();}}
async function submitPayment(){if(!guard('CORP_MAKER'))return;const q=getQuote(),error=quoteErrors(q,state,now());if(error)return toast('Cannot submit: '+error,true);if(!document.querySelector('#consent')?.checked)return toast('Confirm that you have reviewed the fees and conditions.',true);if(state.payments.some(p=>p.quote.id===q.id))return toast('This quote is already used by a payment. Open that payment or get a new quote.',true);busy=true;const correlationId=uid('CORR.SUBMIT');const p={id:uid('IFT'),quote:structuredClone(q),createdAt:stamp(),maker:ACTORS[state.role],checker:null,status:'PENDING_APPROVAL',feeStatus:'QUOTED_NOT_COLLECTED',idempotencyKey:uid('IDEMP'),timeline:[{at:stamp(),title:'Maker submitted payment',detail:'Breakdown accepted; nothing debited yet.'}]};await call({from:'IFT Portal',to:'IFT Workflow',method:'POST',path:'/mock/ift/payments',request:{quoteId:q.id,contextHash:q.contextHash,consent:true,tariffVersion:q.tariffVersion},correlationId,purpose:'Create a payment awaiting the checker',explanation:'The maker cannot approve their own payment.'},{paymentId:p.id,status:p.status,feeStatus:p.feeStatus},201);state.payments.unshift(p);state.selectedPayment=p.id;audit('PAYMENT_SUBMITTED',{quoteId:q.id},p.id);busy=false;view='approvals';save();render();toast('Submitted. Switch to the corporate checker role to approve.');}
function timeline(p,title,detail){p.timeline.push({at:stamp(),title,detail});save();}
async function postCore(p,correlationId){const existing=state.coreResults[p.idempotencyKey];if(existing){await call({from:'IFT API',to:'T24 mock',method:'POST',path:'/mock/t24/payment-postings',request:{paymentId:p.id,quoteId:p.quote.id},key:p.idempotencyKey,correlationId,purpose:'Retry with the same key to prevent double charging',explanation:'Returns the existing result; adds no entries and debits nothing.'},{...existing,deduplicated:true},200);return existing;}const q=p.quote;let insufficient=false;if(q.input.currency===q.input.feeCurrency)insufficient=state.balances[q.input.currency]<q.principal+q.senderFees;else insufficient=state.balances[q.input.currency]<q.principal||state.balances[q.input.feeCurrency]<q.senderFees;if(state.scenario==='INSUFFICIENT')insufficient=true;if(insufficient){await call({from:'IFT API',to:'T24 mock',method:'POST',path:'/mock/t24/payment-postings',request:{paymentId:p.id,quoteId:q.id,principal:q.principal,senderFees:q.senderFees},key:p.idempotencyKey,correlationId,purpose:'Check funds for principal and fees',explanation:'Rejects before debiting. Never creates an overdraft automatically.'},{code:'INSUFFICIENT_FUNDS_FOR_PRINCIPAL_AND_FEES',posted:false},422);throw Error('INSUFFICIENT_FUNDS_FOR_PRINCIPAL_AND_FEES');}state.balances[q.input.currency]=round(state.balances[q.input.currency]-q.principal,q.input.currency);state.balances[q.input.feeCurrency]=round(state.balances[q.input.feeCurrency]-q.senderFees,q.input.feeCurrency);const entries=buildLedger(p);state.ledger.push(...entries);const result={paymentId:p.id,postingRef:uid('POST'),assessmentRef:uid('ASSESS'),status:'POSTED',feeStatus:'COLLECTED',entryCount:entries.length,tariffVersion:q.tariffVersion,contextHash:q.contextHash};state.coreResults[p.idempotencyKey]=result;p.postingRef=result.postingRef;save();if(state.scenario==='CORE_TIMEOUT'){await call({from:'IFT API',to:'T24 mock',method:'POST',path:'/mock/t24/payment-postings',request:{paymentId:p.id,quoteId:q.id},key:p.idempotencyKey,correlationId,purpose:'Posting done but the response timed out',explanation:'The core committed before the 504. IFT does not yet know the fee was collected; it must query.'},{code:'GATEWAY_TIMEOUT',postingOutcome:'UNKNOWN_TO_CALLER'},504);throw Error('CORE_POSTING_OUTCOME_UNKNOWN');}await call({from:'IFT API',to:'T24 mock',method:'POST',path:'/mock/t24/payment-postings',request:{paymentId:p.id,quoteId:q.id,principal:q.principal,senderFees:q.senderFees,feeComponents:q.components},key:p.idempotencyKey,correlationId,purpose:'Debit principal and fees atomically in the lab',explanation:'After validation, the core records a single result with the idempotency key. Production needs a transaction/compensation contract.'},result,201);return result;}
async function finishPayment(p,correlationId){p.feeStatus='COLLECTED';p.status='POSTED';timeline(p,'Core confirmed posting',p.postingRef);await call({from:'IFT API',to:'SWIFT adapter mock',method:'POST',path:'/mock/international/payment-dispatch',request:{paymentId:p.id,amount:p.quote.transferAmount,currency:p.quote.input.currency,bearer:p.quote.input.bearer,message:'DEMO_BUSINESS_MESSAGE_NO_REAL_SWIFT'},correlationId,purpose:'Simulate sending the payment instruction',explanation:'No real SWIFT message is created or sent. A technical ACK is not beneficiary received.'},{status:'TECHNICAL_ACK_SIMULATED',messageRef:uid('MSG')});p.status='COMPLETED';timeline(p,'Demo flow complete','Simulated technical ACK received. This does not mean the beneficiary received the funds.');audit('PAYMENT_EXECUTED',{postingRef:p.postingRef},p.id);}
async function approvePayment(){if(!guard('CORP_CHECKER'))return;const p=getPayment();if(!p||p.status!=='PENDING_APPROVAL')return toast('The payment is not awaiting approval.',true);if(p.maker===ACTORS[state.role])return toast('The maker cannot approve their own payment.',true);const error=quoteErrors(p.quote,{...state,form:p.quote.input},now());if(error){p.error=error;audit('APPROVAL_BLOCKED',error,p.id);render();return toast('Approval blocked: '+error+'. Create a new quote.',true);}busy=true;p.checker=ACTORS[state.role];p.status='PROCESSING';timeline(p,'Checker confirmed','Rechecked quote expiry, version and permissions before posting.');render();const correlationId=uid('CORR.EXEC');try{await call({from:'IFT Portal',to:'IFT Workflow',method:'POST',path:`/mock/ift/payments/${p.id}/approve`,request:{checker:p.checker,quoteId:p.quote.id},correlationId,purpose:'Approval by a checker other than the maker',explanation:'Lab policy requires the quote to still be valid at approval time.'},{authorized:true});await postCore(p,correlationId);await finishPayment(p,correlationId);toast('Demo flow complete. Open accounting to check.');}catch(e){p.error=e.message;if(e.message==='CORE_POSTING_OUTCOME_UNKNOWN'){p.status='UNKNOWN';p.feeStatus='UNKNOWN';timeline(p,'IFT outcome unknown','API timeout; do not collect again with a new key.');}else{p.status='FAILED';p.feeStatus='NOT_COLLECTED';timeline(p,'Transaction rejected',e.message);}audit('EXECUTION_EXCEPTION',e.message,p.id);toast(e.message,true);}finally{busy=false;save();render();}}
async function queryCore(){if(!guard('CORP_CHECKER'))return;const p=getPayment();if(!p||p.status!=='UNKNOWN')return;busy=true;const result=state.coreResults[p.idempotencyKey];const correlationId=uid('CORR.STATUS');await call({from:'IFT API',to:'T24 mock',method:'GET',path:`/mock/t24/postings/by-key/${p.idempotencyKey}`,request:{idempotencyKey:p.idempotencyKey},correlationId,purpose:'Recover the outcome after a timeout',explanation:'Query only; creates no new debit.'},result||{status:'NOT_FOUND'},result?200:404);if(result){p.error=null;p.postingRef=result.postingRef;timeline(p,'Query found the original posting','Collected once; continuing the mock dispatch without posting again.');await finishPayment(p,correlationId);toast('Recovered; no double charge.');}else{toast('No core result found yet. Keep UNKNOWN and send for review.',true);}busy=false;save();render();}
function showQuote(id){const q=state.quotes.find(x=>x.id===id)||state.payments.find(p=>p.quote.id===id)?.quote;if(!q)return;showDialog('Quote details '+q.id,`${notice('Quote belongs to v'+q.tariffVersion+'. '+q.warnings.join(' '))}<pre class="code">${pretty(q)}</pre>`,'',true);}
function showDiff(){if(!state.draft)return;const rows=state.draft.rules.map(r=>{const old=state.active.rules.find(x=>x.id===r.id);const changes=old?Object.keys(r).filter(k=>JSON.stringify(r[k])!==JSON.stringify(old[k])):['NEW'];return changes.length?`<tr><td class="mono">${esc(r.id)}</td><td>${changes.map(k=>`<div><b>${esc(k)}</b>: <span class="diff-old">${esc(old?.[k]??'—')}</span> → <span class="diff-new">${esc(k==='NEW'?'New record':r[k])}</span></div>`).join('')}</td></tr>`:'';}).filter(Boolean).join('');showDialog('Compare v'+state.active.version+' → v'+state.draft.version,rows?`<table><thead><tr><th>Rule</th><th>Changes</th></tr></thead><tbody>${rows}</tbody></table>`:notice('No rule content differences yet. Incrementing the version can still invalidate old quotes under the lab policy.','info'),'');}
function exportData(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function walkthrough(){showDialog('Practice journey · 8 steps',`<p class="subtle">Start from the seed data. You can skip the fee change and practise a payment straight away on the synced v1.</p><div class="row-list">${[['Bank maker','Create draft → open IFT.OUT.COMMISSION → change the rate or Min → save → submit for approval.'],['Bank checker','Open Compare versions → approve and activate.'],['Bank maker','Open Tariff sync → run the 7-step pipeline.'],['Corporate maker','IFT → enter amount, currency, BIC, OUR/SHA/BEN → get fees.'],['Corporate maker','Read the formula and rule evaluation → review → consent → send for approval.'],['Corporate checker','Approve & execute → view the timeline and core posting.'],['Trainer','API Explorer → select each call → read the request/response and explanation.'],['Trainer','Accounting → reconcile → enter the actual correspondent fee → read the difference.']].map(([r,d],i)=>`<div class="row-item"><span class="step-index">0${i+1}</span><div><h3>${r}</h3><div class="subtle">${d}</div></div></div>`).join('')}</div>`,button('Start at T24 configuration','walk-start','primary'));}
async function scenario(id){if(busy)return;state.scenario=id;state.clockOffset=0;audit('SCENARIO_SELECTED',id);if(['SYNC_FAIL','OLD_EVENT'].includes(id)){state.role='OPS_MAKER';view='sync';}else if(id==='BIC_RULE'){state.role='OPS_MAKER';view='tariffs';toast('Create a draft and add a special rule with BIC DEMOUS33 and priority 200.');}else if(id==='AMBIGUOUS'){state.role='OPS_MAKER';view='tariffs';toast('Create a draft, add an OWN_FEE rule with priority 100 like the standard rule, then approve/sync.');}else if(id==='VERSION_CHANGED'){state.role='CORP_MAKER';view='payment';paymentStep=1;toast('Get a quote first, then go back and approve a new tariff to test the version block.');}else{state.role='CORP_MAKER';view='payment';paymentStep=1;if(id==='BEN')state.form.bearer='BEN';else if(id==='JPY'){state.form.currency='JPY';state.form.amount=100000;state.form.bearer='OUR';}else if(id==='NORMAL'){const initial=createState();state.form=initial.form;}toast(id==='EXPIRED'?'Get a quote, then use the “Expire quote” button on the scenario page.':id==='CORE_TIMEOUT'?'Create and approve a payment; after the timeout use Query core status.':id==='DUPLICATE'?'After the payment completes, choose Resend with the same idempotency key.':id==='INSUFFICIENT'?'Create and approve a payment: the core rejects it before debiting.':'Prepared '+id);}save();render();if(id==='EXPIRED')showDialog('Test quote expiry','<p>1. Get a quote in IFT.<br>2. Use the scenario button below to move the clock forward 180 seconds.<br>3. Submitting/approving the payment must be blocked.</p>',button('Move clock +180 seconds now','expire','primary'));}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;try{switch(action){
 case 'nav':if(busy)return toast('Wait for the running task to finish.',true);if(view==='payment'&&paymentStep===1)readPaymentForm();view=el.dataset.view;filter='';render();window.scrollTo(0,0);break;
 case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;
 case 'close':closeDialog();break;
 case 'help':showHelp(el.dataset.key);break;
 case 'sources':view='guide';render();break;
 case 'guide-close':closeDialog();view='guide';render();break;
 case 'walkthrough':walkthrough();break;
 case 'walk-start':closeDialog();view='tariffs';state.role='OPS_MAKER';save();render();break;
 case 'go-tariff':view='tariffs';render();break;
 case 'go-payment':view='payment';paymentStep=1;render();break;
 case 'go-approvals':view='approvals';render();break;
 case 'go-api':view='api';render();break;
 case 'go-scenarios':view='scenarios';render();if(state.scenario==='EXPIRED'){const main=document.querySelector('.main');main.insertAdjacentHTML('afterbegin',`<div class="notice">${button('Expire quote · +180 seconds','expire','small')}</div>`);}break;
 case 'go-guide':view='guide';render();break;
 case 'new-draft':if(!guard('OPS_MAKER')||state.draft)break;state.draft={...structuredClone(state.active),version:state.active.version+1,status:'DRAFT',createdBy:ACTORS[state.role],createdAt:stamp(),approvedBy:null,approvedAt:null};audit('TARIFF_DRAFT_CREATED',{baseVersion:state.active.version},state.draft.id);save();render();toast('Created draft v'+state.draft.version);break;
 case 'edit-rule':editRule(el.dataset.id);break;
 case 'add-rule':if(guard('OPS_MAKER')&&state.draft?.status==='DRAFT')editRule(null,true);break;
 case 'save-rule':{if(!guard('OPS_MAKER')||state.draft?.status!=='DRAFT')break;const data=new FormData(document.querySelector('#rule-form'));const r={...selectedRule};delete r.isNew;for(const k of ['id','name','component','event','method','currency','paymentCurrency','bearer','channel','segment','bic','gl','description'])r[k]=String(data.get(k)||'').trim();for(const k of ['fixed','min','priority'])r[k]=Number(data.get(k));r.rate=Number(data.get('rate'))/100;r.discount=Number(data.get('discount'))/100;r.max=data.get('max')===''?null:Number(data.get('max'));r.enabled=data.has('enabled');r.taxable=data.has('taxable');const errors=ruleErrors(r);if(state.draft.rules.some(x=>x.id===r.id&&(selectedRule.isNew||x.id!==selectedRule.id)))errors.push('Record ID already exists.');if(errors.length){toast(errors.join(' '),true);break;}const index=state.draft.rules.findIndex(x=>x.id===selectedRule.id);if(selectedRule.isNew)state.draft.rules.push(r);else state.draft.rules[index]=r;audit('RULE_SAVED',{ruleId:r.id,version:state.draft.version},r.id);closeDialog();save();render();toast('Rule saved to draft.');break;}
 case 'submit-draft':if(!guard('OPS_MAKER')||state.draft?.status!=='DRAFT')break;{const errors=state.draft.rules.flatMap(r=>ruleErrors(r));if(errors.length){toast(errors.join(' '),true);break;}state.draft.status='PENDING_APPROVAL';state.draft.submittedBy=ACTORS[state.role];audit('TARIFF_SUBMITTED',{version:state.draft.version},state.draft.id);save();render();toast('Switch to the bank checker role to approve.');}break;
 case 'approve-draft':if(!guard('OPS_CHECKER')||state.draft?.status!=='PENDING_APPROVAL')break;state.draft.status='ACTIVE';state.draft.approvedBy=ACTORS[state.role];state.draft.approvedAt=stamp();state.active=structuredClone(state.draft);state.draft=null;audit('TARIFF_ACTIVATED',{version:state.active.version,event:'FeeTariff.Activated'},state.active.id);save();render();toast('Activated v'+state.active.version+'. Sync to IFT is required.');break;
 case 'reject-draft':if(guard('OPS_CHECKER')&&state.draft){state.draft.status='DRAFT';audit('TARIFF_RETURNED','Checker returned the draft to the maker.',state.draft.id);save();render();}break;
 case 'effective':if(guard('OPS_MAKER')&&state.draft?.status==='DRAFT')showDialog('Tariff effective dates',`<form id="effective-form"><div class="form-grid">${field('Effective from','effectiveFrom',state.draft.effectiveFrom,'date')}${field('Effective to','effectiveTo',state.draft.effectiveTo,'date')}</div>${notice('The lab activates immediately after approval, but only quotes when today falls within the effective period. The simulation uses the UTC business date.')}<div class="gap-top">${button('Save dates to draft','save-effective','primary')}</div></form>`);break;
 case 'save-effective':{if(!guard('OPS_MAKER')||state.draft?.status!=='DRAFT')break;const fd=new FormData(document.querySelector('#effective-form'));const from=String(fd.get('effectiveFrom')),to=String(fd.get('effectiveTo'));if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to){toast('Enter valid dates, with the end date not before the start date.',true);break;}state.draft.effectiveFrom=from;state.draft.effectiveTo=to;audit('TARIFF_DATES_CHANGED',{from,to},state.draft.id);closeDialog();save();render();break;}
 case 'sync-step':{const run=state.syncRuns[0],step=run?.steps[Number(el.dataset.step)];if(!step){toast('This step has not run yet.');break;}const log=state.logs.find(l=>l.id===step.apiId);if(log)showDialog(step.name,`<p class="subtle">${esc(log.from)} → ${esc(log.to)} · ${esc(log.method)} ${esc(log.path)} · HTTP ${log.status}</p><h3>Request</h3><pre class="code">${pretty(log.request)}</pre><h3 class="gap-top">Response</h3><pre class="code">${pretty(log.response)}</pre><p class="subtle gap-top">${esc(log.explanation)}</p>`,'',true);break;}
 case 'diff':showDiff();break;
 case 'sync':await runSync();break;
 case 'stale':if(guard('OPS_MAKER')){state.ift.version=Math.max(0,state.active.version-1);audit('REPLICA_STALE_INJECTED',{version:state.ift.version});save();render();}break;
 case 'sample':if(guard('CORP_MAKER')){state.form=createState().form;state.selectedQuote=null;paymentStep=1;save();render();}break;
 case 'quote':event.preventDefault();await getFees();break;
 case 'payment-step':if(view==='payment'&&paymentStep===1&&!readPaymentForm())break;paymentStep=Number(el.dataset.step);render();break;
 case 'quote-detail':showQuote(el.dataset.id||state.selectedQuote);break;
 case 'quote-api':filter=el.dataset.id;view='api';render();break;
 case 'submit-payment':await submitPayment();break;
 case 'select-payment':state.selectedPayment=el.dataset.id;save();render();break;
 case 'approve-payment':await approvePayment();break;
 case 'reject-payment':if(guard('CORP_CHECKER')){const p=getPayment();if(p?.status==='PENDING_APPROVAL'){p.status='REJECTED';p.feeStatus='NOT_COLLECTED';timeline(p,'Checker rejected','Nothing debited.');audit('PAYMENT_REJECTED','Checker rejected the payment.',p.id);save();render();}}break;
 case 'query-core':await queryCore();break;
 case 'retry-posting':if(guard('CORP_CHECKER')){busy=true;const p=getPayment(),count=state.ledger.length;await postCore(p,uid('CORR.RETRY'));audit('DUPLICATE_DEDUPED',{entriesBefore:count,entriesAfter:state.ledger.length},p.id);busy=false;save();render();toast('Returned the original posting. Nothing debited and no entries added.');}break;
 case 'select-log':selectedLog=el.dataset.id;render();break;
 case 'api-tab':apiTab=el.dataset.tab;render();break;
 case 'clear-filter':filter='';render();break;
 case 'copy-log':{const l=state.logs.find(x=>x.id===el.dataset.id);try{await navigator.clipboard.writeText(JSON.stringify(l,null,2));toast('API log copied.');}catch{showDialog('JSON to copy',`<pre class="code">${pretty(l)}</pre>`);}break;}
 case 'export':exportData(state,'ift-fee-lab-snapshot.json');break;
 case 'export-logs':exportData(state.logs,'ift-api-traces.json');break;
 case 'export-audit':exportData(state.audit,'ift-audit-trail.json');break;
 case 'scenario':await scenario(el.dataset.scenario);break;
 case 'expire':state.clockOffset+=180000;audit('CLOCK_ADVANCED','+180 seconds');closeDialog();view='payment';paymentStep=3;save();render();toast('The lab clock moved forward 180 seconds. The previous quote has expired.');break;
 case 'reconcile':{if(!guard('OPS_CHECKER'))break;const p=getPayment();if(!p||!['COMPLETED','POSTED','RECONCILED'].includes(p.status))break;const core=state.coreResults[p.idempotencyKey],entries=state.ledger.filter(e=>e.paymentId===p.id);const items=p.quote.components.map(c=>({component:c.component,expected:c.feeSettlement,currency:c.settlementCurrency,posted:round(entries.filter(e=>e.side==='CR'&&e.component===c.component).reduce((s,e)=>s+e.amount,0),c.settlementCurrency)}));p.recon={paymentId:p.id,postingRef:core?.postingRef,tariffVersionMatched:core?.tariffVersion===p.quote.tariffVersion,contextHashMatched:core?.contextHash===p.quote.contextHash,components:items.map(x=>({...x,status:x.expected===x.posted?'MATCHED':'MISMATCH'})),externalActual:p.externalComparison||'AWAITING_EXTERNAL_ADVICE',note:'Internal recon is separate from actual correspondent settlement.'};p.status='RECONCILED';timeline(p,'Internal reconciliation complete','Checked each component, the version and the context hash. The external actual is tracked separately.');audit('INTERNAL_RECONCILED',p.recon,p.id);save();render();toast('Internally reconciled; the external actual is a separate step.');break;}
 case 'external-actual':{if(!guard('OPS_CHECKER'))break;const p=getPayment();const actual=Number(document.querySelector('[name="actualFee"]').value),ref=document.querySelector('[name="adviceRef"]').value.trim();if(!Number.isFinite(actual)||actual<0||!ref)return toast('Enter a non-negative actual and a reference.',true);if(p.adviceRef===ref&&p.externalActual!==undefined)return toast('This advice reference has already been processed; nothing collected again.',true);const estimate=p.quote.components.filter(c=>c.component==='CORRESPONDENT').reduce((s,c)=>s+convert(c.net,c.currency,'USD'),0);p.externalActual=actual;p.adviceRef=ref;p.externalComparison={estimate:round(estimate,'USD'),actual,difference:round(actual-estimate,'USD'),currency:'USD',adviceRef:ref,status:Math.abs(actual-estimate)<.01?'MATCHED':'REVIEW_REQUIRED'};await call({from:'External advice mock',to:'Reconciliation',method:'POST',path:'/mock/correspondent-charge-advice',request:{paymentId:p.id,adviceRef:ref,actualAmount:actual,currency:'USD'},correlationId:uid('CORR.ACTUAL'),purpose:'Receive the actual correspondent fee',explanation:'Never collects the difference automatically; raises an exception for the difference.'},p.externalComparison);audit('EXTERNAL_ADVICE_RECEIVED',p.externalComparison,p.id);save();render();break;}
 case 'reset':pendingAction=()=>{state=createState();busy=false;paymentStep=1;view='overview';save();closeDialog();render();toast('Seed data restored.');};showDialog('Reset the whole demo session?','<p>This deletes drafts, quotes, payments, API logs and the audit trail in this browser. You can export a snapshot first.</p>',button('Export snapshot first','export')+button('Restore seed data','confirm-reset','danger'));break;
 case 'confirm-reset':pendingAction?.();pendingAction=null;break;
 }}catch(error){busy=false;save();render();toast(error.message,true);console.error(error);}});
document.addEventListener('change',event=>{if(event.target.id==='role'){if(busy){event.target.value=state.role;return;}if(view==='payment'&&paymentStep===1)readPaymentForm();state.role=event.target.value;audit('ROLE_SWITCHED',ROLE_NAMES[state.role]);save();render();}if(event.target.name==='syncScenario'){if(busy){render();return;}state.scenario=event.target.value;save();render();}});
document.addEventListener('input',event=>{if(event.target.id==='log-filter'){const position=event.target.selectionStart;filter=event.target.value;render();const input=document.querySelector('#log-filter');input?.focus();input?.setSelectionRange(position,position);}});
document.addEventListener('submit',event=>event.preventDefault());
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeDialog();if(event.key==='Enter'&&event.target.matches('.trace-row,.sync-step'))event.target.click();});
render();
window.iftLab={getState:()=>structuredClone(state),evaluate,reset:()=>{state=createState();save();render();}};
